                    return False
            else:
                return False
        else:
            return False

    if is_valid_suffix(suffix):
        f = suffix[0].upper()
        if f == 'K':
            mult = 1024
        elif f == 'M':
            mult = 1024*1024
        elif f == 'G':
            mult = 1024*1024*1024
        else:
            mult = 1
        size = num * mult
        return (size, True, "")
    else:
        return (0, False, suffix)

