    def eval_js_expr(self, expr_str, env):
        expr_str = expr_str.strip()
        if expr_str == "":
            return None
        if expr_str == "true":
            return True
        if expr_str == "false":
            return False
        if expr_str == "null":
            return None
        if expr_str == "undefined":
            return "undefined"  # sentinel string? We'll handle specially
        # Numbers
        if re.match(r'^-?\d+$', expr_str):
            try:
                return int(expr_str)
            except:
                pass
        if re.match(r'^-?\d+\.\d+$', expr_str):
            try:
                return float(expr_str)
            except:
                pass
        # String literal
        if len(expr_str)>=2 and ((expr_str[0]=='"' and expr_str[-1]=='"') or (expr_str[0]=="'" and expr_str[-1]=="'")):
            # Handle escapes like \n
            inner = expr_str[1:-1]
            # Unescape simple
            inner = inner.replace('\\n','\n').replace('\\t','\t').replace('\\r','\r').replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            return inner
        # Array
        if expr_str.startswith('[') and expr_str.endswith(']'):
            inner = expr_str[1:-1].strip()
            if inner == "":
                return []
            parts = self.split_args(inner)
            return [self.eval_js_expr(p, env) for p in parts]
        # Object
        if expr_str.startswith('{') and expr_str.endswith('}'):
            inner = expr_str[1:-1].strip()
            if inner == "":
                return {}
            parts = self.split_args(inner)
            obj = {}
            for p in parts:
                if ':' in p:
                    k,v = p.split(':',1)
                    k = k.strip()
                    if (k.startswith('"') and k.endswith('"')) or (k.startswith("'") and k.endswith("'")):
                        k = k[1:-1]
                    obj[k] = self.eval_js_expr(v.strip(), env)
                else:
                    # shorthand? key is variable name
                    k = p.strip()
                    if k in env:
                        obj[k] = env[k]
                    elif k in self.globals:
                        obj[k] = self.globals[k]
            return obj
        # Property access chain
        if '.' in expr_str and not expr_str.startswith('.'):
            # Handle a.b.c
            # Need to be careful with numbers like 0.5
            # If expr_str contains only one dot and looks like number, already handled
            # Split by dot but not inside brackets
            # For simplicity, split by dot
            parts = expr_str.split('.')
            # First part may be function call or variable
            base_expr = parts[0]
            base = self.eval_js_expr(base_expr, env)
            for prop in parts[1:]:
                # prop may contain brackets like "platform" or "log"
                prop = prop.strip()
                if not prop:
                    continue
                # If prop contains '(' -> method call? e.g., "log()" but we handle calls separately
                # For chain like console.log, base is dict containing log
                if isinstance(base, dict):
                    if prop in base:
                        base = base[prop]
                    else:
                        # try to get from global if base is console?
                        base = None
                        break
                else:
                    # If base is None, etc.
                    base = None
                    break
            return base
        # Variable access
        if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', expr_str):
            if expr_str in env:
                return env[expr_str]
            if expr_str in self.globals:
                # Handle undefined sentinel
                v = self.globals[expr_str]
                if v == "undefined":
                    return "undefined"
                return v
            if self.strict:
                raise ReferenceError(f"'{expr_str}' is not defined")
            raise ReferenceError(f"'{expr_str}' is not defined")
        # Function call and other expressions handled elsewhere
        # Try Python eval fallback for arithmetic
        try:
            py_expr = expr_str.replace('true','True').replace('false','False').replace('null','None').replace('undefined','None')
            py_expr = py_expr.replace('===','==').replace('!==','!=')
            combined = {}
            combined.update(self.globals)
            combined.update(env)
            # Safe eval: only allow math etc
            return eval(py_expr, {"__builtins__": {}, "math": math, "True": True, "False": False, "None": None}, combined)
        except ReferenceError:
            raise
        except Exception:
            return expr_str

    def split_args(self, s):
        parts = []
        depth = 0
        current = ""
        in_str = False
        str_char = ''
        escape = False
        for c in s:
            if escape:
                current+=c
                escape=False
                continue
            if c == '\\':
                escape=True
                current+=c
                continue
            if not in_str and c in ('"', "'"):
                in_str = True
                str_char = c
                current+=c
            elif in_str and c == str_char:
                in_str = False
                current+=c
            elif not in_str and c in ('[','{','('):
                depth+=1
                current+=c
            elif not in_str and c in (']','}',')'):
                depth-=1
                current+=c
            elif not in_str and c == ',' and depth==0:
                parts.append(current.strip())
                current=""
            else:
                current+=c
        if current.strip():
            parts.append(current.strip())
        return parts

    def eval_code(self, code, filename="<cmdline>", module_type=AUTODETECT, script_args=None):
        if script_args is not None:
            self.globals['scriptArgs'] = script_args
        else:
            if 'scriptArgs' not in self.globals:
                self.globals['scriptArgs'] = []

        # Handle empty
        if code.strip() == "":
            return 0

        # If module type detection needed, but we will treat all as script except for import handling
        # Handle imports first
        # Extract import statements and remove them, setting globals

        # Pattern for import * as X from 'Y'
        # We'll process line by line for simplicity

        # First, handle file-level import {x} from path that requires loading module

        # For module files that have export and side effects, we need to execute side effects
        # Our earlier logic for module loading included executing module code for side effects

        # For eval_code, we will attempt to handle console.log, variable decl, assignment, throw, etc.

        # We'll split code into statements using ; and newline, but keeping braces
        # This is complex, so we will do a simple line-based approach for now

        # For throw handling
        if 'throw' in code:
            m = re.search(r'throw\s+new\s+Error\s*\(\s*["\']([^"\']+)["\']\s*\)', code)
            if m:
                msg = m.group(1)
                # Format error
                if filename == "<cmdline>":
                    sys.stderr.write(f"Error: {msg}\n    at <eval> (<cmdline>:1:16)\n")
                else:
                    sys.stderr.write(f"Error: {msg}\n    at <eval> ({filename}:1:16)\n")
                sys.exit(1)
            m = re.search(r'throw\s+new\s+Error', code)
            if m:
                sys.stderr.write(f"Error: Error\n    at <eval> ({filename}:1:16)\n")
                sys.exit(1)

        # Handle strict mode implicit global assignment detection: we already handle in eval loop below

        # For Promise rejection handling
        if 'Promise.reject' in code or 'new Promise' in code and 'reject' in code:
            # If no_unhandled flag is False, we should print unhandled rejection
            # Extract error message if possible
            m = re.search(r"new Error\(['\"]([^'\"]+)['\"]\)", code)
            err_msg = m.group(1) if m else "oops"
            if 'Promise.reject' in code:
                # console.log('after') etc - need to handle that the code after should still execute
                # For simplicity, if code is "Promise.reject(new Error('oops')); console.log('after')"
                # We should print 'after' then possibly unhandled rejection error
                # We'll try to handle by executing console.log parts before throwing rejection error
                # Extract console.log parts
                for cm in re.finditer(r'console\.log\s*\(([^)]*)\)', code):
                    args_str = cm.group(1)
                    # Evaluate args
                    args_list = self.split_args(args_str)
                    evaluated = []
                    for a in args_list:
                        try:
                            evaluated.append(self.eval_js_expr(a, {}))
                        except:
                            evaluated.append(a)
                    self.console_log(*evaluated)
                if not self.no_unhandled:
                    sys.stdout.flush()
                    if 'reject' in code:
                        sys.stderr.write(f"Possibly unhandled promise rejection: Error: {err_msg}\n    at <anonymous> ({filename}:1:25)\n")
                        sys.exit(1)
                    else:
                        # For new Promise((r,j)=>{j(...)})
                        sys.stderr.write(f"Possibly unhandled promise rejection: Error: {err_msg}\n    at <anonymous> ({filename}:1:32)\n    at Promise (native)\n    at <eval> ({filename}:1:12)\n")
                        sys.exit(1)
                else:
                    sys.exit(0)

        # General execution: try to handle line by line
        local_env = {}

        # Preprocess: remove import/export statements that we've already handled? For now handle import * as os/std

        # Handle import * as X from 'Y'
        # We'll remove these lines and set globals

        lines = code.split('\n')
        cleaned_lines = []
        for line in lines:
            stripped = line.strip().rstrip(';')
            if stripped.startswith('import'):
                # import * as os from 'os'
                m = re.match(r"import\s+\*\s+as\s+(\w+)\s+from\s+['\"]([^'\"]+)['\"]", stripped)
                if m:
                    var_name = m.group(1)
                    mod_name = m.group(2)
                    if mod_name == 'os':
                        self.globals[var_name] = self.make_os()
                    elif mod_name == 'std':
                        self.globals[var_name] = self.make_std()
                    else:
                        # Load module file
                        mod_path = mod_name
                        if os.path.exists(mod_path):
                            mod_code = open(mod_path).read()
                            # Execute module for side effects
                            sub = JSInterpreter(std_enabled=self.std_enabled, strict=self.strict)
                            sub.globals['scriptArgs'] = [mod_path]
                            sub.eval_code(mod_code, filename=mod_path, module_type=MODULE, script_args=[mod_path])
                            # Try to capture exports: look for export const
                            exports = {}
                            for exp_match in re.finditer(r'export\s+(?:const|let|var)\s+(\w+)\s*=\s*([^\n;]+)', mod_code):
                                ename = exp_match.group(1)
                                eval_str = exp_match.group(2).strip()
                                # Remove trailing stuff
                                # Simple eval
                                try:
                                    if eval_str.isdigit():
                                        exports[ename] = int(eval_str)
                                    else:
                                        # String?
                                        if (eval_str.startswith('"') and eval_str.endswith('"')) or (eval_str.startswith("'") and eval_str.endswith("'")):
                                            exports[ename] = eval_str[1:-1]
                                        else:
                                            exports[ename] = eval_str
                                except:
                                    exports[ename] = eval_str
                            self.globals[var_name] = exports
                        else:
                            self.globals[var_name] = {}
                    continue
                # import {a,b} from 'path'
                m = re.match(r"import\s+{([^}]+)}\s+from\s+['\"]([^'\"]+)['\"]", stripped)
                if m:
                    imports = [x.strip() for x in m.group(1).split(',')]
                    mod_path = m.group(2)
                    if os.path.exists(mod_path):
                        mod_code = open(mod_path).read()
                        sub = JSInterpreter(std_enabled=self.std_enabled, strict=self.strict)
                        sub.globals['scriptArgs'] = [mod_path]
                        sub.eval_code(mod_code, filename=mod_path, module_type=MODULE, script_args=[mod_path])
                        for imp in imports:
                            # Find export
                            pat = rf"export\s+(?:const|let|var)\s+{re.escape(imp)}\s*=\s*([^\n;]+)"
                            m2 = re.search(pat, mod_code)
                            if m2:
                                vs = m2.group(1).strip()
                                try:
                                    if vs.isdigit():
                                        self.globals[imp] = int(vs)
                                    elif (vs.startswith('"') and vs.endswith('"')) or (vs.startswith("'") and vs.endswith("'")):
                                        self.globals[imp] = vs[1:-1]
                                    else:
                                        # Try to eval as number
                                        self.globals[imp] = int(vs) if vs.lstrip('-').isdigit() else vs
                                except:
                                    self.globals[imp] = vs
                    continue
                # import without braces but with default? skip
                continue
            if stripped.startswith('export'):
                # For export, we should execute the declaration without export keyword
                # e.g., export const x=1; -> const x=1;
                # export const x=1; console.log('module') -> two statements in one line separated by ;
                # We'll split by ; and handle each
                # Remove 'export' keyword
                rest = stripped[len('export'):].strip()
                # rest may be "const x=1" or "let x=1" or "function ..."
                # For simplicity, if rest starts with const/let/var, handle as declaration
                # If rest is like "const a=1; console.log('mod')" we have already split by newline, but there may be ; inside
                # We'll split rest by ';' and process
                sub_parts = rest.split(';')
                for part in sub_parts:
                    part = part.strip()
                    if not part:
                        continue
                    # If part is const/let/var declaration, handle
                    m_decl = re.match(r'(?:const|let|var)\s+(\w+)\s*=\s*(.+)', part)
                    if m_decl:
                        vn = m_decl.group(1)
                        ve = m_decl.group(2).strip()
                        try:
                            vv = self.eval_js_expr(ve, local_env)
                            local_env[vn] = vv
                            self.globals[vn] = vv
                        except:
                            pass
                        continue
                    # If part is console.log, handle
                    if 'console.log' in part:
                        # Use same logic as below
                        for cm in re.finditer(r'console\.log\s*\((.*)\)', part):
                            args_str = cm.group(1)
                            args_list = self.split_args(args_str)
                            evaluated = []
                            for a in args_list:
                                try:
                                    evaluated.append(self.eval_js_expr(a, local_env))
                                except ReferenceError as re_err:
                                    sys.stderr.write(f"ReferenceError: {re_err}\n    at <eval> ({filename}:1:1)\n")
                                    sys.exit(1)
                                except Exception:
                                    evaluated.append(a)
                            self.console_log(*evaluated)
                        continue
                    # For other, add to cleaned_lines for later?
                    cleaned_lines.append(part)
                continue
            cleaned_lines.append(line)

        # Reassemble cleaned code (without import/export lines)
        code_clean = "\n".join(cleaned_lines)

