    def is_valid_suffix(suf):
        if len(suf) == 0:
            return True
        first = suf[0]
        if first in 'kK':
            if len(suf) == 1:
                return True
            elif len(suf) == 2:
                if suf[1] in 'iI' or suf[1] in 'bB':
                    return True
                else:
                    return False
            elif len(suf) == 3:
                if suf[1] in 'iI' and suf[2] in 'bB':
                    return True
                else:
                    return False
            else:
                return False
        elif first == 'M':
            if len(suf) == 1:
                return True
            elif len(suf) == 2:
                if suf[1] in 'iI' or suf[1] in 'bB':
                    return True
                else:
                    return False
            elif len(suf) == 3:
                if suf[1] in 'iI' and suf[2] in 'bB':
                    return True
                else:
                    return False
            else:
                return False
        elif first == 'G':
            if len(suf) == 1:
                return True
            elif len(suf) == 2:
                if suf[1] in 'iI' or suf[1] in 'bB':
                    return True
                else:
                    return False
            elif len(suf) == 3:
                if suf[1] in 'iI' and suf[2] in 'bB':
                    return True
                else:
                    return False
            else:
                return False
        else:
            return False

    if is_valid_suffix(suffix):
        f = suffix[0].upper()
        if f == 'K':
            mult = 1024
        elif f == 'M':
            mult = 1024*1024
        elif f == 'G':
            mult = 1024*1024*1024
        else:
            mult = 1
        size = num * mult
        return (size, True, "")
    else:
        return (0, False, suffix)

