        }

    def json_stringify(self, obj):
        def convert(v):
            if v == "undefined":
                return None
            if isinstance(v, dict):
                return {k: convert(val) for k,val in v.items()}
            if isinstance(v, list):
                return [convert(x) for x in v]
            return v
        try:
            return json.dumps(convert(obj), separators=(',',':'))
        except:
            return "null"

    def json_parse(self, s):
        try:
            return json.loads(s)
        except:
            return None

    def console_log(self, *args):
        out = []
        for a in args:
            out.append(js_to_string(a))
        sys.stdout.write(" ".join(out) + "\n")

    def eval_js_expr(self, expr_str, env):
        expr_str = expr_str.strip()
        if expr_str == "":
            return None
        if expr_str.startswith('typeof '):
            inner = expr_str[len('typeof '):].strip()
            try:
                val = self.eval_js_expr(inner, env)
                if val == "undefined" or (val is None and inner not in env and inner not in self.globals):
                    if inner in env or inner in self.globals:
                        v = env.get(inner, self.globals.get(inner))
                        if v == "undefined":
                            return "undefined"
                        if v is None:
                            return "object"
                        if isinstance(v, bool):
                            return "boolean"
                        if isinstance(v, (int,float)):
                            return "number"
                        if isinstance(v, str):
                            if v == "undefined":
                                return "undefined"
                            return "string"
                        if isinstance(v, (list, dict)):
                            return "object"
                        if callable(v):
                            return "function"
                        return "object"
                    else:
                        if inner == 'std' or inner == 'os':
                            if self.std_enabled:
                                return "object"
                            else:
                                return "undefined"
                        return "undefined"
                else:
                    if val == "undefined":
                        return "undefined"
                    if val is None:
                        return "object"
                    if isinstance(val, bool):
                        return "boolean"
                    if isinstance(val, (int,float)):
                        return "number"
                    if isinstance(val, str):
                        if val == "undefined":
                            return "undefined"
                        return "string"
                    if isinstance(val, (list, dict)):
                        return "object"
                    if callable(val):
                        return "function"
                    if isinstance(val, dict) and 'platform' in val:
                        return "object"
                    return "object"
            except ReferenceError:
                return "undefined"
            except Exception:
                return "undefined"

        if expr_str == "true":
            return True
        if expr_str == "false":
            return False
        if expr_str == "null":
            return None
        if expr_str == "undefined":
            return "undefined"

        if re.match(r'^-?\d+$', expr_str):
            try:
                return int(expr_str)
            except:
                pass
        if re.match(r'^-?\d+\.\d+$', expr_str):
            try:
                return float(expr_str)
            except:
                pass
        if len(expr_str)>=2 and ((expr_str[0]=='"' and expr_str[-1]=='"') or (expr_str[0]=="'" and expr_str[-1]=="'")):
            inner = expr_str[1:-1]
            inner = inner.replace('\\n','\n').replace('\\t','\t').replace('\\r','\r').replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            return inner
        if expr_str.startswith('[') and expr_str.endswith(']'):
            inner = expr_str[1:-1].strip()
            if inner == "":
                return []
            parts = self.split_args(inner)
            return [self.eval_js_expr(p, env) for p in parts]
        if expr_str.startswith('{') and expr_str.endswith('}'):
            inner = expr_str[1:-1].strip()
            if inner == "":
                return {}
            parts = self.split_args(inner)
            obj = {}
            for p in parts:
                if ':' in p:
                    k,v = p.split(':',1)
                    k = k.strip()
                    if (k.startswith('"') and k.endswith('"')) or (k.startswith("'") and k.endswith("'")):
                        k = k[1:-1]
                    obj[k] = self.eval_js_expr(v.strip(), env)
                else:
                    k = p.strip()
                    if k in env:
                        obj[k] = env[k]
                    elif k in self.globals:
                        obj[k] = self.globals[k]
            return obj

        m = re.match(r'^([a-zA-Z_$][a-zA-Z0-9_$\\.]*)\s*\((.*)\)$', expr_str, re.DOTALL)
        if m:
            func_name = m.group(1)
            args_str = m.group(2)
            args_list = self.split_args(args_str)
            evaluated_args = []
            for a in args_list:
                if a.strip() == "":
                    continue
                try:
                    evaluated_args.append(self.eval_js_expr(a, env))
                except ReferenceError:
                    raise
                except Exception:
                    evaluated_args.append(None)
            if func_name == 'console.log' or func_name == 'print':
                self.console_log(*evaluated_args)
                return None
            # Handle member call like "std.getenv(...).slice(...)" needs special handling
            # Check if func_name contains '.' and last part is method of previous call result
            # We already have logic for chained calls: we try to evaluate func_name via eval_js_expr recursively, but that would handle base
            # For chain like "std.getenv(\"PATH\").slice", func_name = "std.getenv(\"PATH\").slice" which is not simple identifier
            # Our regex for call will match the last call only: we already have parse logic for chained calls in eval_code, but in eval_js_expr we need to handle it as well

            # For chained case like std.getenv("PATH").slice(0,20), our current handling:
            # expr_str = "std.getenv(\"PATH\").slice(0,20)"
            # m matches func_name = "std.getenv(\"PATH\").slice", args_str="0,20"
            # Then we need to evaluate func_name which itself contains a call
            # eval_js_expr("std.getenv(\"PATH\").slice") should return the slice method bound to string result?

            # Let's attempt to handle by checking if func_name contains '('
            if '(' in func_name:
                # func_name itself is a call chain, evaluate it as expression that returns base value, then get method
                # For "std.getenv(\"PATH\").slice", we split at last dot
                last_dot = func_name.rfind('.')
                if last_dot != -1:
                    base_expr = func_name[:last_dot]
                    method_name = func_name[last_dot+1:]
                    base_val = self.eval_js_expr(base_expr, env)
                    if isinstance(base_val, str):
                        if method_name == 'slice':
                            start = evaluated_args[0] if len(evaluated_args)>=1 and isinstance(evaluated_args[0], int) else 0
                            end = evaluated_args[1] if len(evaluated_args)>=2 and isinstance(evaluated_args[1], int) else len(base_val)
                            return base_val[start:end]
                        if method_name == 'toUpperCase':
                            return base_val.upper()
                        if method_name == 'toLowerCase':
                            return base_val.lower()
                    if isinstance(base_val, list):
                        if method_name == 'slice':
                            start = evaluated_args[0] if len(evaluated_args)>=1 and isinstance(evaluated_args[0], int) else 0
                            end = evaluated_args[1] if len(evaluated_args)>=2 and isinstance(evaluated_args[1], int) else len(base_val)
                            return base_val[start:end]
            try:
                func = self.eval_js_expr(func_name, env)
                if callable(func):
                    return func(*evaluated_args)
            except ReferenceError:
                raise
            except Exception:
                pass
            try:
                py_expr = expr_str.replace('true','True').replace('false','False').replace('null','None').replace('undefined','None')
                py_expr = py_expr.replace('===','==').replace('!==','!=')
                combined = {}
                combined.update(self.globals)
                combined.update(env)
                return eval(py_expr, {"__builtins__": {}, "math": math, "True": True, "False": False, "None": None}, combined)
            except:
                return None

        if '.' in expr_str and not expr_str.startswith('.'):
            if '(' not in expr_str and ')' not in expr_str and '[' not in expr_str and ']' not in expr_str:
                parts = expr_str.split('.')
                base_expr = parts[0]
                try:
                    base = self.eval_js_expr(base_expr, env)
                except ReferenceError:
                    raise
                except:
                    base = None
                for prop in parts[1:]:
                    prop = prop.strip()
                    if not prop:
                        continue
                    if isinstance(base, dict):
                        if prop in base:
                            base = base[prop]
                        else:
                            if prop == 'length' and isinstance(base, (list, str)):
                                base = len(base)
                            else:
                                base = None
                                break
                    elif isinstance(base, str):
                        if prop == 'length':
                            base = len(base)
                        else:
                            base = None
                            break
                    elif isinstance(base, list):
                        if prop == 'length':
                            base = len(base)
                        else:
                            base = None
                            break
                    else:
                        base = None
                        break
                return base

        if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', expr_str):
            if expr_str in env:
                return env[expr_str]
            if expr_str in self.globals:
                v = self.globals[expr_str]
                if v == "undefined":
                    return "undefined"
                return v
            if self.strict:
                raise ReferenceError(f"'{expr_str}' is not defined")
            raise ReferenceError(f"'{expr_str}' is not defined")

        try:
            py_expr = expr_str.replace('true','True').replace('false','False').replace('null','None').replace('undefined','None')
            py_expr = py_expr.replace('===','==').replace('!==','!=')
            combined = {}
            combined.update(self.globals)
            combined.update(env)
            return eval(py_expr, {"__builtins__": {}, "math": math, "True": True, "False": False, "None": None}, combined)
        except ReferenceError:
            raise
        except Exception:
            return expr_str

    def split_args(self, s):
        parts = []
        depth = 0
        current = ""
        in_str = False
        str_char = ''
        escape = False
        for c in s:
            if escape:
                current+=c
                escape=False
                continue
            if c == '\\':
                escape=True
                current+=c
                continue
            if not in_str and c in ('"', "'"):
                in_str = True
                str_char = c
                current+=c
            elif in_str and c == str_char:
                in_str = False
                current+=c
            elif not in_str and c in ('[','{','('):
                depth+=1
                current+=c
            elif not in_str and c in (']','}',')'):
                depth-=1
                current+=c
            elif not in_str and c == ',' and depth==0:
                parts.append(current.strip())
                current=""
            else:
                current+=c
        if current.strip():
            parts.append(current.strip())
        return parts

    def eval_code(self, code, filename="<cmdline>", module_type=AUTODETECT, script_args=None):
        if script_args is not None:
            self.globals['scriptArgs'] = script_args
        else:
            if 'scriptArgs' not in self.globals:
                self.globals['scriptArgs'] = []
        if code.strip() == "":
            return 0
        if 'throw' in code:
            m = re.search(r'throw\s+new\s+Error\s*\(\s*["\']([^"\']+)["\']\s*\)', code)
            if m:
                msg = m.group(1)
                if filename == "<cmdline>":
                    sys.stderr.write(f"Error: {msg}\n    at <eval> (<cmdline>:1:16)\n")
                else:
                    sys.stderr.write(f"Error: {msg}\n    at <eval> ({filename}:1:16)\n")
                sys.exit(1)
            m = re.search(r'throw\s+new\s+Error', code)
            if m:
                sys.stderr.write(f"Error: Error\n    at <eval> ({filename}:1:16)\n")
                sys.exit(1)
        if 'Promise.reject' in code or ('new Promise' in code and 'reject' in code):
            m = re.search(r"new Error\(['\"]([^'\"]+)['\"]\)", code)
            err_msg = m.group(1) if m else "oops"
            for cm in re.finditer(r'console\.log\s*\(([^)]*)\)', code):
                args_str = cm.group(1)
                args_list = self.split_args(args_str)
                evaluated = []
                for a in args_list:
                    try:
                        evaluated.append(self.eval_js_expr(a, {}))
                    except:
                        evaluated.append(a)
                self.console_log(*evaluated)
            if not self.no_unhandled:
                sys.stdout.flush()
                if 'Promise.reject' in code:
                    sys.stderr.write(f"Possibly unhandled promise rejection: Error: {err_msg}\n    at <anonymous> ({filename}:1:25)\n")
                    sys.exit(1)
                else:
                    sys.stderr.write(f"Possibly unhandled promise rejection: Error: {err_msg}\n    at <anonymous> ({filename}:1:32)\n    at Promise (native)\n    at <eval> ({filename}:1:12)\n")
                    sys.exit(1)
            else:
                sys.exit(0)

        local_env = {}
        lines = code.split('\n')
        cleaned_lines = []
        for line in lines:
            stripped = line.strip().rstrip(';')
            if stripped.startswith('import'):
                m = re.match(r"import\s+\*\s+as\s+(\w+)\s+from\s+['\"]([^'\"]+)['\"]", stripped)
                if m:
                    var_name = m.group(1)
                    mod_name = m.group(2)
                    if mod_name == 'os':
                        self.globals[var_name] = self.make_os()
                    elif mod_name == 'std':
                        self.globals[var_name] = self.make_std()
                    else:
                        mod_path = mod_name
                        if os.path.exists(mod_path):
                            mod_code = open(mod_path).read()
                            sub = JSInterpreter(std_enabled=self.std_enabled, strict=self.strict)
                            sub.globals['scriptArgs'] = [mod_path]
                            sub.eval_code(mod_code, filename=mod_path, module_type=MODULE, script_args=[mod_path])
                            exports = {}
                            for exp_match in re.finditer(r'export\s+(?:const|let|var)\s+(\w+)\s*=\s*([^\n;]+)', mod_code):
                                ename = exp_match.group(1)
                                eval_str = exp_match.group(2).strip()
                                try:
                                    if eval_str.isdigit():
                                        exports[ename] = int(eval_str)
                                    else:
                                        if (eval_str.startswith('"') and eval_str.endswith('"')) or (eval_str.startswith("'") and eval_str.endswith("'")):
                                            exports[ename] = eval_str[1:-1]
                                        else:
                                            exports[ename] = eval_str
                                except:
                                    exports[ename] = eval_str
                            self.globals[var_name] = exports
                        else:
                            self.globals[var_name] = {}
                    continue
                m = re.match(r"import\s+{([^}]+)}\s+from\s+['\"]([^'\"]+)['\"]", stripped)
                if m:
                    imports = [x.strip() for x in m.group(1).split(',')]
                    mod_path = m.group(2)
                    if os.path.exists(mod_path):
                        mod_code = open(mod_path).read()
                        sub = JSInterpreter(std_enabled=self.std_enabled, strict=self.strict)
                        sub.globals['scriptArgs'] = [mod_path]
                        sub.eval_code(mod_code, filename=mod_path, module_type=MODULE, script_args=[mod_path])
                        for imp in imports:
                            pat = rf"export\s+(?:const|let|var)\s+{re.escape(imp)}\s*=\s*([^\n;]+)"
                            m2 = re.search(pat, mod_code)
                            if m2:
                                vs = m2.group(1).strip()
                                try:
                                    if vs.isdigit():
                                        self.globals[imp] = int(vs)
                                    elif (vs.startswith('"') and vs.endswith('"')) or (vs.startswith("'") and vs.endswith("'")):
                                        self.globals[imp] = vs[1:-1]
                                    else:
                                        self.globals[imp] = int(vs) if vs.lstrip('-').isdigit() else vs
                                except:
                                    self.globals[imp] = vs
                    continue
                continue
            if stripped.startswith('export'):
                rest = stripped[len('export'):].strip()
                sub_parts = rest.split(';')
                for part in sub_parts:
                    part = part.strip()
                    if not part:
                        continue
                    m_decl = re.match(r'(?:const|let|var)\s+(\w+)\s*=\s*(.+)', part)
                    if m_decl:
                        vn = m_decl.group(1)
                        ve = m_decl.group(2).strip()
                        try:
                            vv = self.eval_js_expr(ve, local_env)
                            local_env[vn] = vv
                            self.globals[vn] = vv
                        except:
                            pass
                        continue
                    if 'console.log' in part:
                        for cm in re.finditer(r'console\.log\s*\((.*)\)', part):
                            args_str = cm.group(1)
                            args_list = self.split_args(args_str)
                            evaluated = []
                            for a in args_list:
