            'random': lambda: __import__('random').random(),
            'abs': lambda x: abs(x),
            'max': lambda *args: max(*args) if args else None,
            'min': lambda *args: min(*args) if args else None,
        }
        self.globals['Object'] = {
            'keys': lambda o: list(o.keys()) if isinstance(o, dict) else [],
        }
        self.globals['Array'] = {}
        self.globals['String'] = {}
        self.globals['Number'] = {}
        self.globals['Boolean'] = {}
        if self.std_enabled:
            self.globals['std'] = self.make_std()
            self.globals['os'] = self.make_os()
        else:
            self.globals['std'] = "undefined"
            self.globals['os'] = "undefined"

    def make_std(self):
        def std_open(*a):
            return None
        def std_popen(*a):
            return None
        def std_tmpfile():
            return None
        def std_puts(s):
            print(s)
        def std_printf(fmt, *a):
            try:
                out = ""
                arg_idx = 0
                i = 0
                while i < len(fmt):
                    if fmt[i] == '%' and i+1 < len(fmt):
                        nxt = fmt[i+1]
                        if nxt == 'd' or nxt == 'i':
                            if arg_idx < len(a):
                                out += str(int(a[arg_idx]))
                                arg_idx+=1
                            i+=2
                            continue
                        elif nxt == 's':
                            if arg_idx < len(a):
                                out += str(a[arg_idx])
                                arg_idx+=1
                            i+=2
                            continue
                        elif nxt == '%':
                            out += '%'
                            i+=2
                            continue
                    out+=fmt[i]
                    i+=1
                sys.stdout.write(out)
            except:
                sys.stdout.write(fmt)
        def std_sprintf(fmt, *a):
            try:
                out = ""
                arg_idx = 0
                i = 0
                while i < len(fmt):
                    if fmt[i] == '%' and i+1 < len(fmt):
                        nxt = fmt[i+1]
                        if nxt == 'd' or nxt == 'i':
                            if arg_idx < len(a):
                                out += str(int(a[arg_idx]))
                                arg_idx+=1
                            i+=2
                            continue
                        elif nxt == 's':
                            if arg_idx < len(a):
                                out += str(a[arg_idx])
                                arg_idx+=1
                            i+=2
                            continue
                        elif nxt == '%':
                            out += '%'
                            i+=2
                            continue
                    out+=fmt[i]
                    i+=1
                return out
            except:
                return fmt
        return {
            'printf': std_printf,
            'sprintf': std_sprintf,
            'open': std_open,
            'popen': std_popen,
            'tmpfile': std_tmpfile,
            'puts': std_puts,
            'getenv': lambda k: os.getenv(k),
            'setenv': lambda k,v: os.environ.__setitem__(k,v),
            'unsetenv': lambda k: os.environ.pop(k, None),
            'getenviron': lambda: dict(os.environ),
            'urlGet': lambda *a: "",
            'parseExtJSON': lambda s: json.loads(s),
            'SEEK_SET': 0,
            'SEEK_CUR': 1,
            'SEEK_END': 2,
            'Error': Exception,
            'gc': lambda: None,
            'loadFile': lambda f: open(f).read() if os.path.exists(f) else None,
            'strerror': lambda n: os.strerror(n) if n>=0 else "Unknown error",
            'exit': lambda c=0: sys.exit(c),
            'evalScript': lambda s: self.eval_code(s),
            'loadScript': lambda f: self.eval_file(f),
            'out': sys.stdout,
            'err': sys.stderr,
            'in': sys.stdin,
