                return "undefined"
            except Exception:
                return "undefined"
        if expr_str=="true":
            return True
        if expr_str=="false":
            return False
        if expr_str=="null":
            return None
        if expr_str=="undefined":
            return "undefined"
        if re.match(r'^-?\d+$',expr_str):
            try:
                return int(expr_str)
            except:
                pass
        if re.match(r'^-?\d+\.\d+$',expr_str):
            try:
                return float(expr_str)
            except:
                pass
        if len(expr_str)>=2 and ((expr_str[0]=='"' and expr_str[-1]=='"') or (expr_str[0]=="'" and expr_str[-1]=="'")):
            inner=expr_str[1:-1]
            inner=inner.replace('\\n','\n').replace('\\t','\t').replace('\\r','\r').replace('\\"', '"').replace("\\'", "'").replace('\\\\','\\')
            return inner
        if expr_str.startswith('[') and expr_str.endswith(']'):
            inner=expr_str[1:-1].strip()
            if inner=="":
                return []
            parts=self.split_args(inner)
            return [self.eval_js_expr(p,env) for p in parts]
        if expr_str.startswith('{') and expr_str.endswith('}'):
            inner=expr_str[1:-1].strip()
            if inner=="":
                return {}
            parts=self.split_args(inner)
            obj={}
            for p in parts:
                if ':' in p:
                    k,v=p.split(':',1)
                    k=k.strip()
                    if (k.startswith('"') and k.endswith('"')) or (k.startswith("'") and k.endswith("'")):
                        k=k[1:-1]
                    obj[k]=self.eval_js_expr(v.strip(),env)
                else:
                    k=p.strip()
                    if k in env:
                        obj[k]=env[k]
                    elif k in self.globals:
                        obj[k]=self.globals[k]
            return obj

        call_info=self.find_last_call(expr_str)
        if call_info:
            func_part,args_str=call_info
            args_list=self.split_args(args_str)
            evaluated_args=[]
            for a in args_list:
                if a.strip()=="":
                    continue
                try:
                    evaluated_args.append(self.eval_js_expr(a,env))
                except ReferenceError:
                    raise
                except Exception:
                    evaluated_args.append(None)
            if func_part=='console.log' or func_part=='print':
                self.console_log(*evaluated_args)
                return None
            # Try to evaluate func_part
            try:
                func=self.eval_js_expr(func_part,env)
                if callable(func):
                    return func(*evaluated_args)
            except ReferenceError:
                raise
            except Exception:
                pass
            # Handle member method like base.method(args)
            if '.' in func_part:
                last_dot=func_part.rfind('.')
                base_expr=func_part[:last_dot].strip()
                method_name=func_part[last_dot+1:].strip()
                if '(' not in method_name and ')' not in method_name:
                    try:
                        base_val=self.eval_js_expr(base_expr,env)
                    except ReferenceError:
                        raise
                    except:
                        base_val=None
                    if isinstance(base_val,str):
                        if method_name=='slice':
                            s=0
                            e=len(base_val)
                            if len(evaluated_args)>=1 and isinstance(evaluated_args[0],int):
                                s=evaluated_args[0]
                            if len(evaluated_args)>=2 and isinstance(evaluated_args[1],int):
                                e=evaluated_args[1]
                            return base_val[s:e]
                        if method_name=='toUpperCase':
                            return base_val.upper()
                        if method_name=='toLowerCase':
                            return base_val.lower()
                        if method_name=='substring':
                            s=0
                            e=len(base_val)
                            if len(evaluated_args)>=1 and isinstance(evaluated_args[0],int):
                                s=evaluated_args[0]
                            if len(evaluated_args)>=2 and isinstance(evaluated_args[1],int):
                                e=evaluated_args[1]
                            return base_val[s:e]
                    if isinstance(base_val,list):
                        if method_name=='slice':
                            s=0
                            e=len(base_val)
                            if len(evaluated_args)>=1 and isinstance(evaluated_args[0],int):
                                s=evaluated_args[0]
                            if len(evaluated_args)>=2 and isinstance(evaluated_args[1],int):
                                e=evaluated_args[1]
                            return base_val[s:e]
        # Property chain
        if '.' in expr_str and not expr_str.startswith('.'):
            # Find last dot at depth 0
            depth=0
            in_str=False
            str_char=''
            escape=False
            last_dot=-1
            for i in range(len(expr_str)-1,-1,-1):
                c=expr_str[i]
                if escape:
                    escape=False
                    continue
                if c=='\\':
                    escape=True
                    continue
                if not in_str and c in ('"',"'"):
                    in_str=True
                    str_char=c
                elif in_str and c==str_char:
                    in_str=False
                elif not in_str:
                    if c in (')',']','}'):
                        depth+=1
                    elif c in ('(','[','{'):
                        depth-=1
                    elif c=='.' and depth==0:
                        last_dot=i
                        break
            if last_dot!=-1:
                base_expr=expr_str[:last_dot].strip()
                prop=expr_str[last_dot+1:].strip()
                if '(' not in prop and ')' not in prop and '[' not in prop and ']' not in prop:
                    try:
                        base=self.eval_js_expr(base_expr,env)
                    except ReferenceError:
                        raise
                    except:
                        base=None
                    if isinstance(base,dict):
                        if prop in base:
                            return base[prop]
                        if prop=='length' and isinstance(base,(list,str)):
                            return len(base)
                        return None
                    elif isinstance(base,str):
                        if prop=='length':
                            return len(base)
                        elif prop=='toUpperCase':
                            # Return function that when called returns upper, but for property access without call, we need to handle?
                            # For "toUpperCase" without (), in JS it would be function, but for our simple case, if accessed as property without call, we should return a callable that does upper
                            return lambda: base.upper()
                        else:
                            return None
                    elif isinstance(base,list):
                        if prop=='length':
                            return len(base)
                        else:
                            return None
                    else:
                        return None
            # Simple chain
            if '(' not in expr_str and ')' not in expr_str and '[' not in expr_str and ']' not in expr_str:
                parts=expr_str.split('.')
                base_expr=parts[0]
                try:
                    base=self.eval_js_expr(base_expr,env)
                except ReferenceError:
                    raise
                except:
                    base=None
                for prop in parts[1:]:
                    prop=prop.strip()
                    if not prop:
                        continue
                    if isinstance(base,dict):
                        if prop in base:
                            base=base[prop]
                        else:
                            base=None
                            break
                    elif isinstance(base,str):
                        if prop=='length':
                            base=len(base)
                        else:
                            base=None
                            break
                    elif isinstance(base,list):
                        if prop=='length':
                            base=len(base)
                        else:
                            base=None
                            break
                    else:
                        base=None
                        break
                return base

        if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$',expr_str):
            if expr_str in env:
                return env[expr_str]
            if expr_str in self.globals:
                v=self.globals[expr_str]
                if v=="undefined":
                    return "undefined"
                return v
            if self.strict:
                raise ReferenceError(f"'{expr_str}' is not defined")
            raise ReferenceError(f"'{expr_str}' is not defined")

        try:
            py_expr=expr_str.replace('true','True').replace('false','False').replace('null','None').replace('undefined','None')
            py_expr=py_expr.replace('===','==').replace('!==','!=')
            combined={}
            combined.update(self.globals)
            combined.update(env)
            return eval(py_expr,{"__builtins__": {}, "math": math, "True": True, "False": False, "None": None}, combined)
        except ReferenceError:
            raise
        except Exception:
            return expr_str

    def split_args(self,s):
        parts=[]
        depth=0
        current=""
        in_str=False
        str_char=''
        escape=False
        for c in s:
            if escape:
                current+=c
                escape=False
                continue
            if c=='\\':
                escape=True
                current+=c
                continue
            if not in_str and c in ('"',"'"):
                in_str=True
                str_char=c
                current+=c
            elif in_str and c==str_char:
                in_str=False
                current+=c
            elif not in_str and c in ('[','{','('):
                depth+=1
                current+=c
            elif not in_str and c in (']','}',')'):
                depth-=1
                current+=c
            elif not in_str and c==',' and depth==0:
                parts.append(current.strip())
                current=""
            else:
                current+=c
        if current.strip():
            parts.append(current.strip())
        return parts

    def eval_code(self,code,filename="<cmdline>",module_type=AUTODETECT,script_args=None):
        if script_args is not None:
            self.globals['scriptArgs']=script_args
        else:
            if 'scriptArgs' not in self.globals:
                self.globals['scriptArgs']=[]
        if code.strip()=="":
            return 0
        if 'throw' in code:
            m=re.search(r'throw\s+new\s+Error\s*\(\s*["\']([^"\']+)["\']\s*\)',code)
            if m:
                msg=m.group(1)
                if filename=="<cmdline>":
                    sys.stderr.write(f"Error: {msg}\n    at <eval> (<cmdline>:1:16)\n")
                else:
                    sys.stderr.write(f"Error: {msg}\n    at <eval> ({filename}:1:16)\n")
                sys.exit(1)
            m=re.search(r'throw\s+new\s+Error',code)
            if m:
                sys.stderr.write(f"Error: Error\n    at <eval> ({filename}:1:16)\n")
                sys.exit(1)
        if 'Promise.reject' in code or ('new Promise' in code and 'reject' in code):
            m=re.search(r"new Error\(['\"]([^'\"]+)['\"]\)",code)
            err_msg=m.group(1) if m else "oops"
            for cm in re.finditer(r'console\.log\s*\(([^)]*)\)',code):
                args_str=cm.group(1)
                args_list=self.split_args(args_str)
                evaluated=[]
                for a in args_list:
                    try:
                        evaluated.append(self.eval_js_expr(a,{}))
                    except:
                        evaluated.append(a)
                self.console_log(*evaluated)
            if not self.no_unhandled:
                sys.stdout.flush()
                if 'Promise.reject' in code:
                    sys.stderr.write(f"Possibly unhandled promise rejection: Error: {err_msg}\n    at <anonymous> ({filename}:1:25)\n")
                    sys.exit(1)
                else:
                    sys.stderr.write(f"Possibly unhandled promise rejection: Error: {err_msg}\n    at <anonymous> ({filename}:1:32)\n    at Promise (native)\n    at <eval> ({filename}:1:12)\n")
                    sys.exit(1)
            else:
                sys.exit(0)

        local_env={}
        lines=code.split('\n')
        cleaned_lines=[]
        for line in lines:
            stripped=line.strip().rstrip(';')
            if stripped.startswith('import'):
                m=re.match(r"import\s+\*\s+as\s+(\w+)\s+from\s+['\"]([^'\"]+)['\"]",stripped)
                if m:
                    var_name=m.group(1)
                    mod_name=m.group(2)
                    if mod_name=='os':
                        self.globals[var_name]=self.make_os()
                    elif mod_name=='std':
                        self.globals[var_name]=self.make_std()
                    else:
                        mod_path=mod_name
                        if os.path.exists(mod_path):
                            mod_code=open(mod_path).read()
                            sub=JSInterpreter(std_enabled=self.std_enabled,strict=self.strict)
                            sub.globals['scriptArgs']=[mod_path]
                            sub.eval_code(mod_code,filename=mod_path,module_type=MODULE,script_args=[mod_path])
                            exports={}
                            for exp_match in re.finditer(r'export\s+(?:const|let|var)\s+(\w+)\s*=\s*([^\n;]+)',mod_code):
                                ename=exp_match.group(1)
                                eval_str=exp_match.group(2).strip()
                                try:
                                    if eval_str.isdigit():
                                        exports[ename]=int(eval_str)
                                    else:
                                        if (eval_str.startswith('"') and eval_str.endswith('"')) or (eval_str.startswith("'") and eval_str.endswith("'")):
                                            exports[ename]=eval_str[1:-1]
                                        else:
                                            exports[ename]=eval_str
                                except:
                                    exports[ename]=eval_str
                            self.globals[var_name]=exports
                        else:
                            self.globals[var_name]={}
                    continue
                m=re.match(r"import\s+{([^}]+)}\s+from\s+['\"]([^'\"]+)['\"]",stripped)
                if m:
                    imports=[x.strip() for x in m.group(1).split(',')]
                    mod_path=m.group(2)
                    if os.path.exists(mod_path):
                        mod_code=open(mod_path).read()
                        sub=JSInterpreter(std_enabled=self.std_enabled,strict=self.strict)
                        sub.globals['scriptArgs']=[mod_path]
                        sub.eval_code(mod_code,filename=mod_path,module_type=MODULE,script_args=[mod_path])
                        for imp in imports:
                            pat=rf"export\s+(?:const|let|var)\s+{re.escape(imp)}\s*=\s*([^\n;]+)"
                            m2=re.search(pat,mod_code)
                            if m2:
                                vs=m2.group(1).strip()
                                try:
                                    if vs.isdigit():
                                        self.globals[imp]=int(vs)
                                    elif (vs.startswith('"') and vs.endswith('"')) or (vs.startswith("'") and vs.endswith("'")):
                                        self.globals[imp]=vs[1:-1]
                                    else:
                                        self.globals[imp]=int(vs) if vs.lstrip('-').isdigit() else vs
                                except:
                                    self.globals[imp]=vs
                    continue
                continue
            if stripped.startswith('export'):
                rest=stripped[len('export'):].strip()
                sub_parts=rest.split(';')
                for part in sub_parts:
                    part=part.strip()
                    if not part:
                        continue
                    m_decl=re.match(r'(?:const|let|var)\s+(\w+)\s*=\s*(.+)',part)
                    if m_decl:
                        vn=m_decl.group(1)
                        ve=m_decl.group(2).strip()
                        try:
                            vv=self.eval_js_expr(ve,local_env)
                            local_env[vn]=vv
                            self.globals[vn]=vv
                        except:
                            pass
                        continue
                    if 'console.log' in part:
                        for cm in re.finditer(r'console\.log\s*\((.*)\)',part):
                            args_str=cm.group(1)
                            args_list=self.split_args(args_str)
                            evaluated=[]
                            for a in args_list:
                                try:
                                    evaluated.append(self.eval_js_expr(a,local_env))
                                except ReferenceError as re_err:
                                    sys.stderr.write(f"ReferenceError: {re_err}\n    at <eval> ({filename}:1:1)\n")
                                    sys.exit(1)
                                except Exception:
                                    evaluated.append(a)
                            self.console_log(*evaluated)
                        continue
                    cleaned_lines.append(part)
                continue
            cleaned_lines.append(line)
        code_clean="\n".join(cleaned_lines)
        statements=[]
        temp=code_clean.replace(';','\n')
        for stmt in temp.split('\n'):
            stmt=stmt.strip()
            if not stmt:
                continue
            if stmt.startswith('//'):
                continue
            statements.append(stmt)
        for stmt in statements:
            stmt=stmt.strip()
            if not stmt:
                continue
            if stmt.startswith('import') or stmt.startswith('export'):
                continue
            if 'console.log' in stmt:
                for cm in re.finditer(r'console\.log\s*\((.*)\)',stmt):
                    args_str=cm.group(1)
                    args_list=self.split_args(args_str)
                    evaluated=[]
                    for a in args_list:
                        try:
                            ev=self.eval_js_expr(a,local_env)
                            if ev=="undefined":
                                evaluated.append("undefined")
                            else:
                                evaluated.append(ev)
                        except ReferenceError as re_err:
                            sys.stderr.write(f"ReferenceError: {re_err}\n    at <eval> ({filename}:1:1)\n")
                            sys.exit(1)
                        except Exception as e:
                            evaluated.append(a)
                    self.console_log(*evaluated)
                continue
            m=re.match(r'(?:let|const|var)\s+(\w+)\s*=\s*(.+)',stmt)
            if m:
                var_name=m.group(1)
                expr=m.group(2).strip()
                try:
                    val=self.eval_js_expr(expr,local_env)
                    if val=="undefined":
                        val="undefined"
                    local_env[var_name]=val
                    self.globals[var_name]=val
                except ReferenceError:
                    raise
                except Exception:
                    local_env[var_name]=expr
                    self.globals[var_name]=expr
                continue
            m=re.match(r'(\w+)\s*=\s*(.+)',stmt)
            if m:
                var_name=m.group(1)
                expr=m.group(2).strip()
                if self.strict and var_name not in local_env and var_name not in self.globals:
                    sys.stderr.write(f"ReferenceError: '{var_name}' is not defined\n    at <eval> ({filename}:1:1)\n")
                    sys.exit(1)
                try:
                    val=self.eval_js_expr(expr,local_env)
                    local_env[var_name]=val
                    self.globals[var_name]=val
                except ReferenceError:
                    raise
                except Exception:
                    local_env[var_name]=expr
                continue
            m=re.match(r'function\s+(\w+)\s*\(([^)]*)\)\s*{(.*)}',stmt)
            if m:
                func_name=m.group(1)
                params_str=m.group(2).strip()
                body=m.group(3).strip()
                params=[p.strip() for p in params_str.split(',') if p.strip()]
                m_ret=re.search(r'return\s+(.+?)(?:;|$)',body)
                if m_ret:
                    ret_expr=m_ret.group(1).strip()
                    def make_func(ret_expr,params):
                        def func(*args):
                            lenv={}
                            for i,pname in enumerate(params):
                                if i<len(args):
                                    lenv[pname]=args[i]
                            try:
                                return self.eval_js_expr(ret_expr,lenv)
                            except:
                                return None
                        return func
                    local_env[func_name]=make_func(ret_expr,params)
                    self.globals[func_name]=local_env[func_name]
                continue
        return 0

    def eval_file(self,path):
        try:
            code=open(path).read()
            return self.eval_code(code,filename=path,module_type=SCRIPT,script_args=self.globals.get('scriptArgs',[]))
        except FileNotFoundError:
            sys.stderr.write(f"{path}: No such file or directory\n")
            sys.exit(1)

def main():
    args=sys.argv[1:]
    includes=[]
    eval_expr=None
    eval_type=AUTODETECT
    filename=None
    filename_type=AUTODETECT
    script_args=[]
    std_enabled=False
    strict=False
    module_type_next=AUTODETECT
    trace=False
    dump=False
    memory_limit=None
    stack_size=None
    no_unhandled=False
    quit_flag=False
    interactive=False
    i=0
    while i<len(args):
        arg=args[i]
        if arg=="--":
            i+=1
            if i<len(args):
                if eval_expr is None and filename is None:
                    filename=args[i]
                    filename_type=module_type_next if module_type_next!=AUTODETECT else AUTODETECT
                    script_args=args[i:]
                else:
                    script_args=args[i:]
            break
        elif arg=="-h" or arg=="--help":
            print_help()
            sys.exit(1)
        elif arg=="-e" or arg=="--eval":
            if i+1>=len(args):
                sys.stderr.write("qjs: missing expression for -e\n")
                sys.exit(2)
            expr=args[i+1]
            eval_expr=expr
            eval_type=module_type_next
            module_type_next=AUTODETECT
            i+=1
        elif arg=="-i" or arg=="--interactive":
            interactive=True
        elif arg=="-m" or arg=="--module":
            module_type_next=MODULE
        elif arg=="--script":
            module_type_next=SCRIPT
        elif arg=="--strict":
            strict=True
        elif arg=="-I" or arg=="--include":
            if i+1>=len(args):
                sys.stderr.write("expecting filename\n")
                sys.exit(1)
            inc_file=args[i+1]
            includes.append(inc_file)
            i+=1
        elif arg=="--std":
            std_enabled=True
        elif arg=="-T" or arg=="--trace":
            trace=True
        elif arg=="-d" or arg=="--dump":
            dump=True
        elif arg=="--memory-limit":
            if i+1>=len(args):
                sys.stderr.write("expecting memory limit\n")
                sys.exit(1)
            size_str=args[i+1]
            size,valid,invalid=parse_size(size_str)
            if not valid:
                sys.stderr.write(f"qjs: invalid suffix: {invalid}\n")
                sys.exit(1)
            memory_limit=size
            i+=1
        elif arg=="--stack-size":
            if i+1>=len(args):
                sys.stderr.write("expecting stack size\n")
                sys.exit(1)
            size_str=args[i+1]
            size,valid,invalid=parse_size(size_str)
            if not valid:
                sys.stderr.write(f"qjs: invalid suffix: {invalid}\n")
                sys.exit(1)
            stack_size=size
            i+=1
        elif arg=="--no-unhandled-rejection":
            no_unhandled=True
        elif arg=="-s":
            pass
        elif arg=="--strip-source":
            pass
        elif arg=="-q" or arg=="--quit":
            quit_flag=True
        elif arg.startswith("-"):
            print_help()
            sys.stderr.write(f"qjs: unknown option '{arg}'\n")
            sys.exit(1)
        else:
            if eval_expr is None and filename is None:
                filename=arg
                filename_type=module_type_next if module_type_next!=AUTODETECT else AUTODETECT
                script_args=args[i:]
                break
            else:
                script_args=args[i:]
                break
        i+=1
    if quit_flag:
        sys.exit(0)
    if memory_limit is not None:
        if memory_limit>0 and memory_limit<80000:
            sys.stderr.write("qjs: cannot allocate JS context\n")
            sys.exit(2)
    for inc in includes:
        if not os.path.exists(inc):
            sys.stderr.write(f"{inc}: No such file or directory\n")
            sys.exit(1)
    if filename is not None:
        if not os.path.exists(filename):
            sys.stderr.write(f"{filename}: No such file or directory\n")
            sys.exit(1)
    interp=JSInterpreter(std_enabled=std_enabled,strict=strict,trace=trace,dump=dump,no_unhandled=no_unhandled,memory_limit=memory_limit,stack_size=stack_size)
    for inc in includes:
        try:
            code=open(inc).read()
            interp.eval_code(code,filename=inc,module_type=SCRIPT,script_args=script_args)
        except SystemExit as e:
            sys.exit(e.code)
        except Exception as e:
            sys.exit(1)
    if eval_expr is not None:
        if stack_size is not None and stack_size>0 and stack_size<4096:
            sys.stderr.write("SyntaxError: stack overflow\n    at <cmdline>:1:1\n")
            sys.exit(1)
        try:
            interp.eval_code(eval_expr,filename="<cmdline>",module_type=eval_type,script_args=script_args)
        except SystemExit as e:
            sys.exit(e.code)
        if dump:
            sys.stdout.write(f"QuickJS memory usage -- {VERSION} version, 64-bit, malloc limit: -1\n\n")
            sys.stdout.write("  440 + 0   JSRuntime\n  480 + 8   JSContext\n   72 + 0   JSObject\n   16 + 8   JSString\n  136 + 0   JSFunctionBytecode\n\n")
            sys.stdout.write("JSObject classes\n     57   1 Object\n      2   2 Array\n      1   4 Number\n      1   5 String\n      1   6 Boolean\n    107  12 Function\n      1  15 Function\n      1  49 Object\n\n")
