                                eval_str=exp_match.group(2).strip()
                                try:
                                    if eval_str.isdigit():
                                        exports[ename]=int(eval_str)
                                    else:
                                        if (eval_str.startswith('"') and eval_str.endswith('"')) or (eval_str.startswith("'") and eval_str.endswith("'")):
                                            exports[ename]=eval_str[1:-1]
                                        else:
                                            exports[ename]=eval_str
                                except:
                                    exports[ename]=eval_str
                            self.globals[var_name]=exports
                        else:
                            self.globals[var_name]={}
                    continue
                m=re.match(r"import\s+{([^}]+)}\s+from\s+['\"]([^'\"]+)['\"]",stripped)
