        code_clean="\n".join(cleaned_lines)
        statements=[]
        temp=code_clean.replace(';','\n')
        for stmt in temp.split('\n'):
            stmt=stmt.strip()
            if not stmt:
                continue
            if stmt.startswith('//'):
                continue
            statements.append(stmt)
        for stmt in statements:
            stmt=stmt.strip()
            if not stmt:
                continue
            if stmt.startswith('import') or stmt.startswith('export'):
                continue
            if 'console.log' in stmt:
                for cm in re.finditer(r'console\.log\s*\((.*)\)',stmt):
                    args_str=cm.group(1)
                    args_list=self.split_args(args_str)
                    evaluated=[]
                    for a in args_list:
                        try:
                            ev=self.eval_js_expr(a,local_env)
                            if ev=="undefined":
                                evaluated.append("undefined")
                            else:
                                evaluated.append(ev)
                        except ReferenceError as re_err:
                            sys.stderr.write(f"ReferenceError: {re_err}\n    at <eval> ({filename}:1:1)\n")
                            sys.exit(1)
