    m=re.match(r'^([+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?)',s)
    if m:
        num_str=m.group(1)
        suffix=s[m.end():]
        try:
            num=float(num_str)
        except:
            num=0.0
    else:
        num=0.0
        suffix=s
    if suffix=="":
        return (num,True,"")
    def is_valid_suffix(suf):
        if len(suf)==0:
            return True
        first=suf[0]
        if first in 'kK':
            if len(suf)==1:
                return True
            elif len(suf)==2:
                return suf[1] in 'iI' or suf[1] in 'bB'
            elif len(suf)==3:
                return suf[1] in 'iI' and suf[2] in 'bB'
            else:
                return False
        elif first=='M':
            if len(suf)==1:
                return True
            elif len(suf)==2:
                return suf[1] in 'iI' or suf[1] in 'bB'
            elif len(suf)==3:
                return suf[1] in 'iI' and suf[2] in 'bB'
            else:
                return False
        elif first=='G':
            if len(suf)==1:
                return True
            elif len(suf)==2:
                return suf[1] in 'iI' or suf[1] in 'bB'
            elif len(suf)==3:
                return suf[1] in 'iI' and suf[2] in 'bB'
            else:
                return False
        else:
            return False
    if is_valid_suffix(suffix):
        f=suffix[0].upper()
        if f=='K':
            mult=1024
        elif f=='M':
            mult=1024*1024
        elif f=='G':
            mult=1024*1024*1024
        else:
            mult=1
        return (num*mult,True,"")
    else:
        return (0,False,suffix)
